"""
verify_geometry_probability.py — 验证概率三部曲动画代码
只使用 numpy，不 import manim
"""
import numpy as np
import re
import sys

FILES = {
    "probability_definition":  "/home/claude/probability_definition.py",
    "probability_enumeration": "/home/claude/probability_enumeration.py",
    "probability_frequency":   "/home/claude/probability_frequency.py",
}

CHINESE_RE = re.compile(r'[\u4e00-\u9fff]')
MATHTEX_RE = re.compile(r'MathTex\(r?["\']([^"\']+)["\']')
TEXT_CMD_RE = re.compile(r'\\text\{([^}]*)\}')

# ──────────────────────────────────────────────────────
def verify_angles(content, name):
    risky = re.findall(r'\b(Angle|ArcBetweenPoints|RightAngle)\b', content)
    if risky:
        print(f"  ⚠️  {name}: 角度对象 {set(risky)} — 手动核查方向")
        return True   # warning only, not blocking
    # Arrow 方向分析
    arrow_re = re.compile(
        r'Arrow\s*\(\s*\n?\s*np\.array\(\[([^\]]+)\]\)'
        r'\s*,\s*\n?\s*np\.array\(\[([^\]]+)\]\)',
        re.MULTILINE,
    )
    issues = []
    for m in arrow_re.finditer(content):
        try:
            s = np.array([float(x) for x in m.group(1).split(",")])
            e = np.array([float(x) for x in m.group(2).split(",")])
            deg = np.degrees(np.arctan2(e[1]-s[1], e[0]-s[0]))
            if abs(deg) > 180:
                issues.append(f"  ⚠️⚠️  Arrow >180°={deg:.1f}° — 可能方向错误!")
            elif abs(deg) > 90:
                issues.append(f"  ⚠️   Arrow >90°={deg:.1f}° — 请确认")
        except Exception:
            pass
    for i in issues:
        print(f"  {name}: {i}")
    print(f"  ✓ {name}: 角度验证通过")
    return True

# ──────────────────────────────────────────────────────
def grep_MathTex(content, name):
    errors = []
    for m in MATHTEX_RE.findall(content):
        if CHINESE_RE.search(m):
            errors.append(f"  ❌ {name}: MathTex 含中文: {m[:65]}")
    for m in TEXT_CMD_RE.findall(content):
        if CHINESE_RE.search(m):
            errors.append(f"  ❌ {name}: \\text{{}} 含中文: {m}")
    if errors:
        for e in errors: print(e)
        return False
    count = len(MATHTEX_RE.findall(content))
    print(f"  ✓ {name}: {count} 个 MathTex，无中文")
    return True

# ──────────────────────────────────────────────────────
def verify_boundaries(content, name):
    X_SAFE, Y_SAFE = 4.0, 7.5
    # 提取所有 move_to(UP/DOWN * N) 和 LEFT/RIGHT * N + UP/DOWN * M
    float_pat = r'[-+]?\d+(?:\.\d+)?'
    errors = []

    # UP * y
    for m in re.finditer(r'move_to\s*\(\s*UP\s*\*\s*(' + float_pat + r')', content):
        y = float(m.group(1))
        if y > Y_SAFE:
            errors.append(f"  ❌ {name}: UP*{y} 超出 y≤{Y_SAFE}")
    # DOWN * y
    for m in re.finditer(r'move_to\s*\(\s*DOWN\s*\*\s*(' + float_pat + r')', content):
        y = float(m.group(1))
        if y > Y_SAFE:
            errors.append(f"  ❌ {name}: DOWN*{y} 超出 y≤{Y_SAFE}")
    # LEFT/RIGHT offset
    for m in re.finditer(r'LEFT\s*\*\s*(' + float_pat + r')', content):
        x = float(m.group(1))
        if x > X_SAFE:
            errors.append(f"  ❌ {name}: LEFT*{x} 超出 x≤{X_SAFE}")
    for m in re.finditer(r'RIGHT\s*\*\s*(' + float_pat + r')', content):
        x = float(m.group(1))
        if x > X_SAFE:
            errors.append(f"  ❌ {name}: RIGHT*{x} 超出 x≤{X_SAFE}")
    # np.array coords
    for m in re.finditer(r'np\.array\(\[(' + float_pat + r')\s*,\s*(' + float_pat + r')', content):
        x, y = float(m.group(1)), float(m.group(2))
        if abs(x) > X_SAFE:
            errors.append(f"  ❌ {name}: np.array x={x} 超出 ±{X_SAFE}")
        if abs(y) > Y_SAFE:
            errors.append(f"  ❌ {name}: np.array y={y} 超出 ±{Y_SAFE}")
    if errors:
        for e in errors: print(e)
        return False
    print(f"  ✓ {name}: 边界验证通过")
    return True

# ──────────────────────────────────────────────────────
def check_forbidden(content, name):
    checks = [
        (r"VGroup\(\*self\.mobjects\)",
         "VGroup(*self.mobjects) → TypeError，改用 *[FadeOut(m)...]"),
        (r"(?<!Rounded)Rectangle\s*\([^)]*corner_radius",
         "Rectangle 不支持 corner_radius，用 RoundedRectangle"),
        (r"Sector\s*\([^)]*inner_radius",
         "Sector.inner_radius 已移除，用 AnnularSector"),
        (r"scale_tips\s*=", "Arrow.scale_tips 不支持"),
    ]
    issues = []
    for pat, msg in checks:
        if re.search(pat, content, re.DOTALL):
            issues.append(f"  ❌ {name}: {msg}")
    if issues:
        for i in issues: print(i)
        return False
    print(f"  ✓ {name}: 无禁用模式")
    return True

# ──────────────────────────────────────────────────────
def verify_latex_syntax(content, name):
    issues = []
    for m in MATHTEX_RE.findall(content):
        if "°" in m:
            issues.append(f"  ❌ {name}: MathTex 含 °（用 ^\\circ）: {m[:50]}")
        if re.search(r'\\[\u4e00-\u9fff]', m):
            issues.append(f"  ❌ {name}: LaTeX 命令后中文: {m[:50]}")
    if issues:
        for i in issues: print(i)
        return False
    print(f"  ✓ {name}: LaTeX 语法正常")
    return True

# ──────────────────────────────────────────────────────
def verify_probability_math():
    """数值验证概率计算正确性"""
    print("\n[概率数值验证]")
    cases = [
        ("P(even|die)",          3/6,   1/2),
        ("P(red|3R2B)",          3/5,   0.6),
        ("P(>4|die)",            2/6,   1/3),
        ("P(HH|2coins)",         1/4,   0.25),
        ("P(>=1H|2coins)",       3/4,   0.75),
        ("P(sum=4|2dice 1-3)",   3/9,   1/3),
        ("freq Buffon",          2048/4040, 0.5069, 0.001),
        ("freq Pearson12k",      6019/12000, 0.5016, 0.0001),
    ]
    ok = True
    for c in cases:
        label, lhs, rhs = c[0], c[1], c[2]
        tol = c[3] if len(c) > 3 else 1e-10
        diff = abs(lhs - rhs)
        status = "✓" if diff < tol else "❌"
        print(f"  {status} {label}: {lhs:.6f} ≈ {rhs:.6f}, diff={diff:.2e}")
        if diff >= tol:
            ok = False
    return ok

# ──────────────────────────────────────────────────────
def run_checks_for_file(name, path):
    with open(path) as f:
        content = f.read()
    results = [
        verify_angles(content, name),
        grep_MathTex(content, name),
        verify_boundaries(content, name),
        check_forbidden(content, name),
        verify_latex_syntax(content, name),
    ]
    return all(results)

# ──────────────────────────────────────────────────────
def main():
    print("=" * 66)
    print("概率三部曲  — 代码验证报告")
    print("=" * 66)

    file_results = {}
    for name, path in FILES.items():
        print(f"\n── {name} ──")
        try:
            file_results[name] = run_checks_for_file(name, path)
        except FileNotFoundError:
            print(f"  ❌ 文件不存在: {path}")
            file_results[name] = False

    print("\n[概率数值验证]")
    math_ok = verify_probability_math()

    print("\n" + "=" * 66)
    print("验证总结")
    print("=" * 66)
    all_pass = True
    for name, ok in file_results.items():
        print(f"  {'✓' if ok else '❌'}  {name}")
        if not ok: all_pass = False
    print(f"  {'✓' if math_ok else '❌'}  概率数值验证")
    if not math_ok: all_pass = False

    print()
    if all_pass:
        print("✅ 全部验证通过！可以渲染。")
        print("\n渲染命令：")
        print("  manim -pql probability_definition.py  ProbabilityDefinition")
        print("  manim -pql probability_enumeration.py ProbabilityEnumeration")
        print("  manim -pql probability_frequency.py   ProbabilityFrequency")
    else:
        print("⚠️  存在问题，请修复后重试。")
    return all_pass

if __name__ == "__main__":
    main()
